<section class="page-intro container-wide"><span class="eyebrow">WELCOME BACK, <?= e(user()['name']) ?></span><h1>Your little corner.</h1></section><section class="container-wide pb-5"><div class="account-grid"><aside class="panel"><h3>Your details</h3><form method="post" action="<?= e(url('profile')) ?>"><?= csrf() ?><label>Full name<input class="form-control" name="name" required value="<?= e(user()['name']) ?>"></label><label>Email<input class="form-control" value="<?= e(user()['email']) ?>" disabled></label><label>Mobile<input class="form-control" name="mobile" value="<?= e(user()['mobile']) ?>"></label><details><summary>Change password</summary><label>Current password<input class="form-control" type="password" name="current_password" autocomplete="current-password"></label><label>New password<input class="form-control" type="password" name="new_password" minlength="10" autocomplete="new-password"></label></details><button class="btn btn-primary w-100 mt-3">Save details</button></form><form method="post" action="<?= e(url('logout')) ?>" class="mt-3"><?= csrf() ?><button class="text-button">Log out</button></form></aside><div><div class="panel"><h2>My orders</h2><?php if(!$orders): ?><p>Your first favourite is waiting in the pantry.</p><a href="<?= e(url('shop')) ?>" class="btn btn-outline-primary">Find a flavour</a><?php endif ?><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= e($o['number']) ?></td><td><?= date('d M Y',strtotime($o['created_at'])) ?></td><td><?= money($o['total']) ?></td><td><span class="status-pill"><?= e($o['status']) ?></span><small class="d-block">Payment: <?= e($o['payment_status']) ?><?= $o['payment_method']==='cod'?' (COD)':'' ?></small></td><td><a class="text-link" href="<?= e(url('order',['id'=>$o['id']])) ?>">Track order →</a></td></tr><?php endforeach ?></tbody></table></div></div><div class="panel mt-4"><h2>Saved addresses</h2><p class="muted">Addresses used at checkout are saved here for your next order.</p><div class="address-grid"><?php foreach($addresses as $a): ?><article><strong><?= e($a['name']) ?></strong><p><?= e($a['address'].', '.$a['city'].' '.$a['pincode']) ?></p><form action="<?= e(url('address/delete')) ?>" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $a['id'] ?>"><button class="text-button">Remove</button></form></article><?php endforeach ?></div></div><div class="panel mt-4"><h2>My reviews</h2><?php foreach($myReviews as $r): ?><p><strong><?= e($r['name']) ?></strong> · <?= $r['rating'] ?>/5 · <?= e($r['status']) ?><br><?= e($r['body']) ?></p><?php endforeach ?><?php if(!$myReviews): ?><p class="muted">After delivery, visit a product page to share your experience.</p><?php endif ?></div></div></div></section>
